// Android patches for Nightmare Depths. Safe to re-run: every step overwrites or checks first.
//  - landscape lock, vibrate permission
//  - fullscreen immersive + keep screen on (MainActivity.java)
//  - launcher icons generated by scripts/icons.mjs (legacy, round and adaptive)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { renderPNG } from './icons.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const cfg = JSON.parse(fs.readFileSync(path.join(root, 'capacitor.config.json'), 'utf8'));
const appId = cfg.appId;
const androidDir = path.join(root, 'android');
if (!fs.existsSync(androidDir)) {
  console.error('[patch-android] android/ not found. Run: npm run android:add');
  process.exit(1);
}
const main = path.join(androidDir, 'app', 'src', 'main');
const res = path.join(main, 'res');

// ---- 1. AndroidManifest.xml ----
const manifestPath = path.join(main, 'AndroidManifest.xml');
let xml = fs.readFileSync(manifestPath, 'utf8');

function setAttr(tag, name, value) {
  const re = new RegExp(name.replace(/[.:]/g, (m) => '\\' + m) + '="[^"]*"');
  if (re.test(tag)) return tag.replace(re, `${name}="${value}"`);
  return tag.replace(/\s*>$/, `\n            ${name}="${value}">`);
}

xml = xml.replace(/<activity\b[^>]*>/, (tag) => {
  tag = setAttr(tag, 'android:screenOrientation', 'sensorLandscape');
  tag = setAttr(tag, 'android:hardwareAccelerated', 'true');
  return tag;
});
if (!/android\.permission\.VIBRATE/.test(xml)) {
  xml = xml.replace('</manifest>', '    <uses-permission android:name="android.permission.VIBRATE" />\n</manifest>');
}
fs.writeFileSync(manifestPath, xml);
console.log('[patch-android] manifest: landscape + vibrate');

// ---- 2. MainActivity.java (immersive fullscreen, screen stays on) ----
const javaDir = path.join(main, 'java', ...appId.split('.'));
fs.mkdirSync(javaDir, { recursive: true });
const java = `package ${appId};

import android.os.Bundle;
import android.view.WindowManager;
import androidx.core.view.WindowCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.core.view.WindowInsetsControllerCompat;
import com.getcapacitor.BridgeActivity;

public class MainActivity extends BridgeActivity {
    @Override
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
        hideSystemBars();
    }

    @Override
    public void onWindowFocusChanged(boolean hasFocus) {
        super.onWindowFocusChanged(hasFocus);
        if (hasFocus) hideSystemBars();
    }

    private void hideSystemBars() {
        WindowCompat.setDecorFitsSystemWindows(getWindow(), false);
        WindowInsetsControllerCompat c = new WindowInsetsControllerCompat(getWindow(), getWindow().getDecorView());
        c.hide(WindowInsetsCompat.Type.systemBars());
        c.setSystemBarsBehavior(WindowInsetsControllerCompat.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);
    }
}
`;
fs.writeFileSync(path.join(javaDir, 'MainActivity.java'), java);
console.log('[patch-android] MainActivity.java: immersive + keep screen on');

// ---- 3. Launcher icons ----
const legacy = { mdpi: 48, hdpi: 72, xhdpi: 96, xxhdpi: 144, xxxhdpi: 192 };
const adaptive = { mdpi: 108, hdpi: 162, xhdpi: 216, xxhdpi: 324, xxxhdpi: 432 };
for (const d of Object.keys(legacy)) {
  const dir = path.join(res, 'mipmap-' + d);
  fs.mkdirSync(dir, { recursive: true });
  for (const f of ['ic_launcher.webp', 'ic_launcher_round.webp', 'ic_launcher_foreground.webp']) { try { fs.unlinkSync(path.join(dir, f)); } catch (e) {} }
  fs.writeFileSync(path.join(dir, 'ic_launcher.png'), renderPNG(legacy[d], 'full', false));
  fs.writeFileSync(path.join(dir, 'ic_launcher_round.png'), renderPNG(legacy[d], 'full', true));
  fs.writeFileSync(path.join(dir, 'ic_launcher_foreground.png'), renderPNG(adaptive[d], 'fg', false));
}
fs.mkdirSync(path.join(res, 'values'), { recursive: true });
fs.writeFileSync(
  path.join(res, 'values', 'ic_launcher_background.xml'),
  '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <color name="ic_launcher_background">#000000</color>\n</resources>\n'
);
const adaptiveXml =
  '<?xml version="1.0" encoding="utf-8"?>\n<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">\n' +
  '    <background android:drawable="@color/ic_launcher_background"/>\n' +
  '    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>\n</adaptive-icon>\n';
fs.mkdirSync(path.join(res, 'mipmap-anydpi-v26'), { recursive: true });
fs.writeFileSync(path.join(res, 'mipmap-anydpi-v26', 'ic_launcher.xml'), adaptiveXml);
fs.writeFileSync(path.join(res, 'mipmap-anydpi-v26', 'ic_launcher_round.xml'), adaptiveXml);
console.log('[patch-android] launcher icons');
console.log('[patch-android] done');
